// A second, articulated goat rig makes dialogue-requested poses visible in-world.
function goat(name,x,z,kind=0,job='villager'){
 let g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
 let clothes=[npcMat.shirt,npcMat.dress,npcMat.vest,npcMat.shirt][kind%4];
 const group=()=>{const q=new THREE.Group();g.add(q);return q},upper=group(),arms=group(),standingLegs=group(),seatedLegs=group();
 seatedLegs.visible=false;
 const part=(parent,geo,m,px,py,pz,sx=1,sy=1,sz=1)=>{let o=new THREE.Mesh(geo,m);o.position.set(px,py,pz);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o};
 part(upper,new THREE.CylinderGeometry(.42,.5,1.05,10),clothes,0,1.25,0);
 part(upper,new THREE.SphereGeometry(.46,10,8),clothes,0,1.65,0,.92,.6,.75);
 part(upper,new THREE.CylinderGeometry(.18,.27,.68,8),npcMat.pants,0,.48,0);
 part(upper,new THREE.SphereGeometry(.29,10,8),npcMat.wool,0,2.1,0,.82,1,.75);
 part(upper,new THREE.SphereGeometry(.29,12,10),npcMat.wool,0,2.28,-.04,.82,1.08,.82);
 part(upper,new THREE.ConeGeometry(.18,.34,10),npcMat.wool,0,2.12,-.32,1,1,.86);
 part(upper,new THREE.SphereGeometry(.12,10,8),mat(0x937e69),0,2.2,-.44,1,.8,.82);
 for(let s of [-1,1]){
  part(upper,new THREE.SphereGeometry(.047,8,7),npcMat.eye,s*.16,2.36,-.255,1,1,.65);
  part(upper,new THREE.ConeGeometry(.09,.47,8),npcMat.horn,s*.2,2.68,.02,1,1,.8).rotation.z=s*.16;
  let ear=part(upper,new THREE.SphereGeometry(.14,9,7),npcMat.wool,s*.35,2.35,.04,kind===1?.7:1.55,kind===1?1.8:.62,.54);ear.rotation.z=s*(kind===1?.28:.12);
  let arm=new THREE.Group();arm.position.set(s*.48,1.55,-.04);arms.add(arm);
  const a=(geo,m,px,py,pz,sx=1,sy=1,sz=1)=>part(arm,geo,m,px,py,pz,sx,sy,sz);
  let sleeve=a(new THREE.CylinderGeometry(.105,.12,.65,7),clothes,0,-.17,0);sleeve.rotation.z=-s*.24;
  a(new THREE.SphereGeometry(.12,8,7),npcMat.wool,s*.07,-.53,-.04);
  arm.userData.side=s;
 }
 for(let s of [-1,1]){
  part(standingLegs,new THREE.CylinderGeometry(.11,.12,.48,7),npcMat.pants,s*.18,.28,.01);
  part(standingLegs,new THREE.SphereGeometry(.14,8,6),npcMat.wool,s*.18,.08,-.13,1.1,.42,1.35);
  for(let t=0;t<5;t++){let tx=s*.18+(t-2)*.045;part(standingLegs,new THREE.SphereGeometry(.035,6,5),npcMat.wool,tx,.055,-.23,1,.75,1.5);part(standingLegs,new THREE.SphereGeometry(.018,5,4),npcMat.hoof,tx,.048,-.27,.8,.4,.7)}
 }
 if(kind===2)part(upper,new THREE.BoxGeometry(.48,.58,.08),npcMat.apron,0,1.14,-.27);
 if(kind===3){let scarf=part(upper,new THREE.TorusGeometry(.23,.07,6,12),npcMat.scarf,0,1.85,0);scarf.rotation.x=Math.PI/2}
 if(job==='elder')part(upper,new THREE.CylinderGeometry(.025,.025,.5,5),mats.wood,.58,.55,-.13).rotation.z=-.1;
 // Bent thighs and crossed shins/feet are revealed when the character sits.
 const segment=(a,b,r,m)=>{let A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),d=B.clone().sub(A),o=new THREE.Mesh(new THREE.CylinderGeometry(r*.82,r,d.length(),8),m);o.position.copy(A.add(B).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());o.castShadow=true;o.receiveShadow=true;seatedLegs.add(o);return o};
 for(let s of [-1,1]){
  const hip=[s*.17,.76,0],knee=[s*.2,.48,-.48],ankle=[-s*.12,.94,-1.23];
  segment(hip,knee,.15,npcMat.pants);segment(knee,ankle,.105,npcMat.pants);
  part(seatedLegs,new THREE.SphereGeometry(.14,9,7),npcMat.wool,ankle[0],ankle[1],ankle[2]-.1,1,.7,1.55);
  for(let t=0;t<5;t++){let tx=ankle[0]+(t-2)*.045;part(seatedLegs,new THREE.SphereGeometry(.034,6,5),npcMat.wool,tx,ankle[1]-.02,ankle[2]-.22,1,.75,1.45);part(seatedLegs,new THREE.SphereGeometry(.018,5,4),npcMat.hoof,tx,ankle[1]-.035,ankle[2]-.255,.8,.4,.7)}
 }
 g.userData={name,job,kind,homeY:0,phase:Math.random()*5,body:g,upper,arms,standingLegs,seatedLegs,pose:'stand',furniture:null};return g
}
const villagers=[goat('Mara',-3,-2,1,'elder'),goat('Tovin',8,-1,2,'shepherd'),goat('Pella',-7,7,3,'baker'),goat('Edda',4,10,0,'villager'),goat('Nim',-12,-12,2,'villager')];

